// Requires: mesh OBJ (File → Open Mesh OBJ)
// Vertex layout: position (float3), normal (float3), UV (float2)

cbuffer Host : register(b0)
{
    float time_sim_ms;
    float time_wall_ms;
    float delta_time_ms;
    uint  frame_index;
    float resolution_x;
    float resolution_y;
    float mouse_x;
    float mouse_y;
    uint  mouse_buttons;
    float scroll_delta_x;
    float scroll_delta_y;
    float drag_accum_x;
    float drag_accum_y;
    float scroll_accum_x;
    float scroll_accum_y;
    float pan_accum_x;
    float pan_accum_y;
};

struct VSIn {
    [[vk::location(0)]] float3 pos : POSITION;
    [[vk::location(1)]] float3 nrm : NORMAL;
    [[vk::location(2)]] float2 uv  : TEXCOORD0;
};

struct VSOut {
    float4 pos : SV_POSITION;
    [[vk::location(0)]] float3 worldNrm : TEXCOORD0;
    [[vk::location(1)]] float2 uv       : TEXCOORD1;
    [[vk::location(2)]] float3 worldPos : TEXCOORD2;
};

float4x4 lookAtRH(float3 eye, float3 at, float3 up)
{
    float3 zaxis = normalize(eye - at);
    float3 xaxis = normalize(cross(up, zaxis));
    float3 yaxis = cross(zaxis, xaxis);
    return float4x4(
        float4(xaxis, -dot(xaxis, eye)),
        float4(yaxis, -dot(yaxis, eye)),
        float4(zaxis, -dot(zaxis, eye)),
        float4(0, 0, 0, 1)
    );
}

float4x4 perspectiveRH(float fovY, float aspect, float zn, float zf)
{
    float f = 1.0f / tan(fovY * 0.5f);
    return float4x4(
        float4(f / aspect, 0, 0, 0),
        float4(0, f, 0, 0),
        float4(0, 0, zf / (zn - zf), (zn * zf) / (zn - zf)),
        float4(0, 0, -1, 0)
    );
}

VSOut VSMain(VSIn i)
{
    VSOut o;

    float yaw = drag_accum_x * 0.01f;
    float pitch = clamp(-drag_accum_y * 0.01f, -1.4f, 1.4f);
    float dist = max(0.5f, 3.0f - scroll_accum_y * 0.3f);

    float3 fwd = float3(sin(yaw)*cos(pitch), sin(pitch), cos(yaw)*cos(pitch));
    float3 right = normalize(cross(float3(0,1,0), fwd));
    float3 up = cross(fwd, right);
    float panScale = dist * 0.002f;
    float3 at = right * (-pan_accum_x * panScale) + up * (pan_accum_y * panScale);
    float3 eye = at + float3(
        dist * cos(pitch) * sin(yaw),
        dist * sin(pitch),
        dist * cos(pitch) * cos(yaw)
    );

    float4x4 V = lookAtRH(eye, at, float3(0, 1, 0));
    float aspect = max(0.001f, resolution_x / max(1.0f, resolution_y));
    float4x4 P = perspectiveRH(radians(60.0f), aspect, 0.05f, 100.0f);

    float4 wp = float4(i.pos, 1.0f);
    o.pos = mul(P, mul(V, wp));
    o.worldNrm = normalize(i.nrm);
    o.worldPos = i.pos;
    o.uv = i.uv;
    return o;
}

cbuffer Host : register(b0)
{
    float time_sim_ms;
    float time_wall_ms;
    float delta_time_ms;
    uint  frame_index;
    float resolution_x;
    float resolution_y;
    float mouse_x;
    float mouse_y;
    uint  mouse_buttons;
    float scroll_delta_x;
    float scroll_delta_y;
    float drag_accum_x;
    float drag_accum_y;
    float scroll_accum_x;
    float scroll_accum_y;
    float pan_accum_x;
    float pan_accum_y;
};

struct GSIn {
    float4 pos : SV_POSITION;
    [[vk::location(0)]] float3 worldNrm : TEXCOORD0;
    [[vk::location(1)]] float2 uv       : TEXCOORD1;
    [[vk::location(2)]] float3 worldPos : TEXCOORD2;
};

struct GSOut {
    float4 pos : SV_POSITION;
    [[vk::location(0)]] float3 worldNrm : TEXCOORD0;
    [[vk::location(1)]] float2 uv       : TEXCOORD1;
    [[vk::location(2)]] float3 worldPos : TEXCOORD2;
    [[vk::location(3)]] float3 bary     : TEXCOORD3;
};

[maxvertexcount(3)]
void GSMain(triangle GSIn input[3], inout TriangleStream<GSOut> stream)
{
    GSOut o;

    // Assign barycentric coordinates to each vertex
    [unroll]
    for (int i = 0; i < 3; i++)
    {
        o.pos = input[i].pos;
        o.worldNrm = input[i].worldNrm;
        o.uv = input[i].uv;
        o.worldPos = input[i].worldPos;

        // Barycentric: vertex 0 = (1,0,0), vertex 1 = (0,1,0), vertex 2 = (0,0,1)
        o.bary = float3(i == 0 ? 1.0f : 0.0f, i == 1 ? 1.0f : 0.0f, i == 2 ? 1.0f : 0.0f);
        stream.Append(o);
    }
    stream.RestartStrip();
}

cbuffer Host : register(b0)
{
    float time_sim_ms;
    float time_wall_ms;
    float delta_time_ms;
    uint  frame_index;
    float resolution_x;
    float resolution_y;
    float mouse_x;
    float mouse_y;
    uint  mouse_buttons;
    float scroll_delta_x;
    float scroll_delta_y;
    float drag_accum_x;
    float drag_accum_y;
    float scroll_accum_x;
    float scroll_accum_y;
    float pan_accum_x;
    float pan_accum_y;
};

struct PSIn {
    float4 pos : SV_POSITION;
    [[vk::location(0)]] float3 worldNrm : TEXCOORD0;
    [[vk::location(1)]] float2 uv       : TEXCOORD1;
    [[vk::location(2)]] float3 worldPos : TEXCOORD2;
    [[vk::location(3)]] float3 bary     : TEXCOORD3;
};

float4 PSMain(PSIn i) : SV_Target
{
    float3 N = normalize(i.worldNrm);
    float3 L = normalize(float3(0.5f, 0.7f, 0.3f));
    float ndl = max(dot(N, L), 0.0f);

    // Solid shading base
    float3 baseColor = float3(0.55f, 0.55f, 0.6f);
    float3 solid = baseColor * (0.2f + 0.8f * ndl);

    // Wireframe from barycentric coordinates
    float3 bary = i.bary;
    float lineWidth = 1.5f;
    float3 d = fwidth(bary);
    float3 a3 = smoothstep(d * (lineWidth - 0.5f), d * (lineWidth + 0.5f), bary);
    float edgeFactor = min(min(a3.x, a3.y), a3.z);

    // Wire color
    float3 wireColor = float3(0.1f, 0.9f, 0.6f);

    // Blend wireframe over solid
    float3 col = lerp(wireColor, solid, edgeFactor);
    return float4(col, 1.0f);
}
